("chrisjbillington/inotify_simple", "pypi", "Minimal, well-behaved Python wrapper over Linux inotify.", "Linux-only watching with no dependencies beyond the wrapper.", "Cross-platform requirements (watchdog).", ["watchdog"], "pip install inotify_simple"),
